namespace sv_318ebbff91344102b16da7a41156639c.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for one circuit.
/// Raises <see cref="OnWarehouseChanged"/> so every subscribing component can react.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId).Name
        ?? _currentWarehouseId;

    public event Func<Task>? OnWarehouseChanged;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;

        if (OnWarehouseChanged is not null)
            await OnWarehouseChanged.Invoke();
    }
}

namespace sv_318ebbff91344102b16da7a41156639c.Services;

/// <summary>
/// Scoped service that simulates low-stock queries and broadcasts results
/// to all subscribed components in the same circuit.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    private int _lastLowStockCount;
    public int LastLowStockCount => _lastLowStockCount;

    /// <summary>Fires after <see cref="RefreshAsync"/> fetches new data.</summary>
    public event Func<int, Task>? OnAlertCountChanged;

    /// <summary>Simulates a database query returning a random 0–15 count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency-free DB call; return random count.
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Fetches the latest count for <paramref name="warehouseId"/> and
    /// notifies every subscriber.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _lastLowStockCount = await GetLowStockCountAsync(warehouseId);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke(_lastLowStockCount);
    }
}

