@using sv_318ebbff91344102b16da7a41156639c.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm" style="width:auto;"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnSelectionChanged">
    @foreach (var (id, name) in WarehouseStateService.AvailableWarehouses)
    {
        <option value="@id">@name</option>
    }
</select>

@code {
    private async Task OnSelectionChanged(ChangeEventArgs e)
    {
        var selected = e.Value?.ToString();
        if (!string.IsNullOrEmpty(selected))
            await WarehouseState.SetWarehouseAsync(selected);
    }

    // Re-render if another component changes the warehouse
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private async Task HandleWarehouseChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

@using sv_318ebbff91344102b16da7a41156639c.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge rounded-pill @BadgeClass">@_count</span>

@code {
    private int _count;

    private string BadgeClass => _count > 0 ? "bg-danger" : "bg-secondary";

    protected override void OnInitialized()
    {
        _count = AlertService.LastLowStockCount;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
    }

    private async Task HandleAlertCountChanged(int newCount)
    {
        _count = newCount;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@using sv_318ebbff91344102b16da7a41156639c.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard – @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-3" style="max-width: 28rem;">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouseName</h5>
        <p class="card-text">
            Low-stock alerts:
            <span class="badge rounded-pill @(_lowStockCount > 0 ? "bg-danger" : "bg-secondary") fs-6">
                @_lowStockCount
            </span>
        </p>
        <p class="text-muted small mb-0">Refreshes every 10 s while this page is open.</p>
    </div>
</div>

@code {
    private int _lowStockCount;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch + start polling
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
